def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Marker columns are indicated by 5s along the bottom edge.
    marker_row = max(r for r in range(h) if 5 in grid[r])
    cols = [c for c, v in enumerate(grid[marker_row]) if v == 5]

    for c in cols:
        seeds = [(r, grid[r][c]) for r in range(marker_row)
                 if grid[r][c] != 0]
        if not seeds:
            continue

        # Extend the first color upward; between successive seeds, extend
        # the lower seed's color upward. The marker color extends below the
        # last seed.
        seeds.sort()
        for r in range(seeds[0][0]):
            if out[r][c] == 0:
                out[r][c] = seeds[0][1]

        for (r1, _), (r2, color) in zip(seeds, seeds[1:]):
            for r in range(r1 + 1, r2):
                if out[r][c] == 0:
                    out[r][c] = color

        last_r = seeds[-1][0]
        for r in range(last_r + 1, marker_row + 1):
            if out[r][c] == 0:
                out[r][c] = 5

    return out
